__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"FIRMWARE",{enumerable:!0,get:function(){return n}});const n="/*\n  Exposoma-PM: sensor caseiro de part\xedculas para o app Exposoma Amaz\xf4nia (PPGSND/UFOPA)\n\n  Pe\xe7as: placa ESP32 DevKit (qualquer uma com Bluetooth) + sensor Plantower PMS5003.\n  Liga\xe7\xf5es (PMS5003 -> ESP32):\n    pino 1 VCC  -> VIN (5 V)\n    pino 2 GND  -> GND\n    pino 4 RX   -> GPIO17 (TX2)\n    pino 5 TX   -> GPIO16 (RX2)\n  Biblioteca: NimBLE-Arduino (vers\xe3o 2.x), instalada pelo Gerenciador de Bibliotecas da Arduino IDE.\n  Placa: \"ESP32 Dev Module\" (pacote esp32 da Espressif).\n\n  O que faz: l\xea o PMS5003 a cada segundo, tira a m\xe9dia de 5 segundos e manda ao celular,\n  por Bluetooth (servi\xe7o UART da Nordic), o texto \"pm25,pm10\" em \xb5g/m\xb3 (valores CF=1, sem corre\xe7\xe3o).\n  O app corrige a umidade e guarda as m\xe9dias por hora.\n*/\n#include <Arduino.h>\n#include <NimBLEDevice.h>\n\n#define NOME_SENSOR   \"Exposoma-PM\"\n#define UUID_SERVICO  \"6e400001-b5a3-f393-e0a9-e50e24dcca9e\"\n#define UUID_TX       \"6e400003-b5a3-f393-e0a9-e50e24dcca9e\"\n#define PINO_RX 16\n#define PINO_TX 17\n\nNimBLECharacteristic* tx = nullptr;\nbool conectado = false;\n\nclass Servidor : public NimBLEServerCallbacks {\n  void onConnect(NimBLEServer* s, NimBLEConnInfo& info) override { conectado = true; }\n  void onDisconnect(NimBLEServer* s, NimBLEConnInfo& info, int motivo) override {\n    conectado = false;\n    NimBLEDevice::startAdvertising();  // volta a anunciar para o celular achar de novo\n  }\n};\n\n// L\xea um quadro de 32 bytes do PMS5003. Devolve true e preenche pm25/pm10 (CF=1) se o quadro for v\xe1lido.\nbool lerPms(uint16_t& pm25, uint16_t& pm10) {\n  while (Serial2.available() >= 32) {\n    if (Serial2.peek() != 0x42) { Serial2.read(); continue; }\n    uint8_t b[32];\n    Serial2.readBytes(b, 32);\n    if (b[0] != 0x42 || b[1] != 0x4D) continue;\n    uint16_t soma = 0;\n    for (int i = 0; i < 30; i++) soma += b[i];\n    uint16_t confere = (b[30] << 8) | b[31];\n    if (soma != confere) continue;\n    pm25 = (b[6] << 8) | b[7];   // PM2,5 CF=1\n    pm10 = (b[8] << 8) | b[9];   // PM10 CF=1\n    return true;\n  }\n  return false;\n}\n\nvoid setup() {\n  Serial.begin(115200);\n  Serial2.begin(9600, SERIAL_8N1, PINO_RX, PINO_TX);\n\n  NimBLEDevice::init(NOME_SENSOR);\n  NimBLEServer* servidor = NimBLEDevice::createServer();\n  servidor->setCallbacks(new Servidor());\n  NimBLEService* servico = servidor->createService(UUID_SERVICO);\n  tx = servico->createCharacteristic(UUID_TX, NIMBLE_PROPERTY::READ | NIMBLE_PROPERTY::NOTIFY);\n  servico->start();\n\n  NimBLEAdvertising* anuncio = NimBLEDevice::getAdvertising();\n  anuncio->setName(NOME_SENSOR);\n  anuncio->addServiceUUID(UUID_SERVICO);\n  anuncio->enableScanResponse(true);\n  anuncio->start();\n  Serial.println(\"Exposoma-PM pronto. Abra o app e toque em Procurar sensor.\");\n}\n\nuint32_t soma25 = 0, soma10 = 0, n = 0;\nunsigned long ultimoEnvio = 0;\n\nvoid loop() {\n  uint16_t pm25, pm10;\n  if (lerPms(pm25, pm10)) {\n    soma25 += pm25; soma10 += pm10; n++;\n  }\n  if (millis() - ultimoEnvio >= 5000 && n > 0) {\n    char msg[24];\n    snprintf(msg, sizeof(msg), \"%.1f,%.1f\", (float)soma25 / n, (float)soma10 / n);\n    Serial.println(msg);\n    tx->setValue((uint8_t*)msg, strlen(msg));\n    if (conectado) tx->notify();\n    soma25 = soma10 = n = 0;\n    ultimoEnvio = millis();\n  }\n  delay(50);\n}\n"},1265,[]);
